    height: 3px;
    background: var(--accent);
    border-radius: 12px 12px 0 0;
  }
  .kpi-card.accent2::after { background: var(--accent2); }
  .kpi-card.green::after { background: var(--positive); }
  .kpi-label { font-size: 11px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: 0.8px; margin-bottom: 8px; }
  .kpi-value { font-size: 28px; font-weight: 700; color: var(--primary); line-height: 1; }
  .kpi-sub { font-size: 12px; color: var(--muted); margin-top: 6px; }

  /* CARDS */
  .card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 24px;
    margin-bottom: 24px;
  }
  .card-title {
    font-size: 14px;
    font-weight: 600;
    color: var(--primary);
    margin-bottom: 16px;
  }

  /* INSIGHT BOX */
  .insight {
    background: #eef3ff;
    border-left: 4px solid var(--accent);
    border-radius: 0 8px 8px 0;
    padding: 14px 18px;
