  }
  .insight strong { color: var(--accent); }
  .insight.warning {
    background: #fff4ee;
    border-color: var(--accent2);
  }
  .insight.warning strong { color: var(--accent2); }

  /* TABLES */
  .data-table { width: 100%; border-collapse: collapse; font-size: 13px; }
