  .compare-table .row-label { text-align: left; font-weight: 600; font-size: 13px; }
  .compare-table .fiction-col { background: #eff6ff; }
  .compare-table .nf-col { background: #fff7ed; }
  .compare-table .winner { font-weight: 700; }

  /* SVG CHARTS */
  .chart-wrapper {
    background: var(--card);
